-- PT122-S1-Q8. Batch 13.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT122-S1-Q8$batch13$ AND q.stimulus=$batch13$Vervet monkeys use different alarm calls to warn each other of nearby predators, depending on whether the danger comes from land or from the air.$batch13$ AND q.prompt=$batch13$Which one of the following, if true, contributes most to an explanation of the behavior of vervet monkeys described above?$batch13$ AND q.correct_choice=$batch13$D$batch13$) THEN RAISE EXCEPTION 'Question changed: PT122-S1-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch13$PT122-S1-Q8$batch13$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT122-S1-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT122-S1-Q8$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Fact$batch13$, $batch13$Vervet monkeys use different alarm calls depending on whether the predator is on land or in the air.$batch13$), (1, $batch13$Evaluate$batch13$, $batch13$Why would the warning need to say where the danger is? One general alarm would tell the monkeys to flee. A separate call is useful only if the right response depends on where the predator comes from.$batch13$), (2, $batch13$Goal$batch13$, $batch13$Find a reason the monkeys need to know whether the threat is on land or in the air.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT122-S1-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Pitch signals how many predators there are. That doesn't explain separate calls for land and air.$batch13$), ($batch13$B$batch13$, $batch13$Different land predators kill different numbers of monkeys. That says nothing about land versus air.$batch13$), ($batch13$C$batch13$, $batch13$This is the most popular trap. It shows the predators fall cleanly into two groups. It doesn't show why the monkeys need to tell those groups apart. If the escape were the same either way, one call would do.$batch13$), ($batch13$D$batch13$, $batch13$The monkeys climb trees to escape land predators and dive into foliage to escape predators in the air. The call tells them which escape to use.$batch13$), ($batch13$E$batch13$, $batch13$What the predators eat doesn't change how the monkeys should escape.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT122-S1-Q8$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
